/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {useEffect, useRef, useState} from 'react';
import type {CSSProperties, PointerEvent as ReactPointerEvent} from 'react';
import './styles.css';

type IconName = 'grid'|'chart'|'folder'|'report'|'settings'|'help'|'chevron'|'plus'|'arrow'|'bell'|'search'|'grip'|'close'|'check'|'download'|'external'|'users'|'wallet'|'cart'|'target'|'calendar'|'expand'|'reset'|'logout'|'sun'|'link';
function Icon({name,size=20,...props}:{name:IconName;size?:number;className?:string;style?:CSSProperties}) {
 const paths:Record<IconName,React.ReactNode>={
 grid:<><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.6\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.6\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.6\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.6\"/></>,
 chart:<><path d=\"M4 4v16h17M8 14l4-5 4 3 5-7\"/></>,folder:<path d=\"M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3z\"/>,report:<><path d=\"M14 3H5v18h14V8zM14 3v6h5M8 13h8M8 17h5\"/></>,settings:<><path d=\"m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></>,help:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01\"/></>,chevron:<path d=\"m9 5 7 7-7 7\"/>,plus:<path d=\"M12 5v14M5 12h14\"/>,arrow:<path d=\"M5 16 16 5M5 5h11v11\"/>,bell:<><path d=\"M5 17h14l-2-4V9A5 5 0 0 0 7 9v4zM10 21h4\"/></>,search:<><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 5 5\"/></>,grip:<><circle cx=\"9\" cy=\"5\" r=\".8\"/><circle cx=\"15\" cy=\"5\" r=\".8\"/><circle cx=\"9\" cy=\"12\" r=\".8\"/><circle cx=\"15\" cy=\"12\" r=\".8\"/><circle cx=\"9\" cy=\"19\" r=\".8\"/><circle cx=\"15\" cy=\"19\" r=\".8\"/></>,close:<path d=\"m6 6 12 12M6 18 18 6\"/>,check:<path d=\"m5 12 4 4L19 6\"/>,download:<><path d=\"M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5\"/></>,external:<><path d=\"M14 3h7v7m0-7L10 14M9 4H3v17h17v-6\"/></>,users:<><circle cx=\"9\" cy=\"8\" r=\"3\"/><path d=\"M3 20v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5\"/></>,wallet:<><rect x=\"3\" y=\"5\" width=\"18\" height=\"15\" rx=\"3\"/><path d=\"M17 5V3H6a3 3 0 0 0-3 3m18 5h-6v5h6M17 13.5h.01\"/></>,cart:<><path d=\"M3 3h2l3 13h11l2-9H6\"/><circle cx=\"9\" cy=\"20\" r=\"1\"/><circle cx=\"18\" cy=\"20\" r=\"1\"/></>,target:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/></>,calendar:<><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"/><path d=\"M7 3v4m10-4v4M3 11h18m-13 4h1m6 0h1\"/></>,expand:<path d=\"M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5\"/>,reset:<><path d=\"M3 10a9 9 0 1 1 1 8M3 4v6h6\"/></>,logout:<path d=\"M10 3H4v18h6m4-5 5-4-5-4m-5 4h10\"/>,sun:<><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2\"/></>,link:<><path d=\"m10 14 4-4m-6 2-3 3a4 4 0 0 0 6 6l3-3m-4-12 3-3a4 4 0 0 1 6 6l-3 3\"/></>};
 return <svg width={size} height={size} viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.65\" strokeLinecap=\"round\" strokeLinejoin=\"round\" {...props}>{paths[name]}</svg>
}
type WidgetKind='revenue'|'customers'|'orders'|'conversion'|'chart'|'traffic'|'projects'|'goal'|'activity';
type Widget={id:string;kind:WidgetKind;x:number;y:number;w:number;h:number};
const initial:Widget[]=[{id:'revenue',kind:'revenue',x:0,y:0,w:3,h:2},{id:'customers',kind:'customers',x:3,y:0,w:3,h:2},{id:'orders',kind:'orders',x:6,y:0,w:3,h:2},{id:'conversion',kind:'conversion',x:9,y:0,w:3,h:2},{id:'chart',kind:'chart',x:0,y:2,w:8,h:4},{id:'traffic',kind:'traffic',x:8,y:2,w:4,h:4},{id:'projects',kind:'projects',x:0,y:6,w:8,h:4},{id:'goal',kind:'goal',x:8,y:6,w:4,h:4}];
const widgetNames:Record<WidgetKind,string>={revenue:'Общая выручка',customers:'Клиенты',orders:'Заказы',conversion:'Конверсия',chart:'Динамика выручки',traffic:'Источники трафика',projects:'Последние проекты',goal:'Цель на месяц',activity:'Активность команды'};
const overlaps=(a:Widget,b:Widget)=>a.id"'!==b.id&&a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
function place(widgets:Widget[],moved:Widget){let next=widgets.map(w=>w.id===moved.id?moved:{...w});let queue=[moved];let attempts=0;while(queue.length&&attempts++<100){const item=queue.shift()!;next=next.map(w=>{if(overlaps(item,w)){const changed={...w,y:item.y+item.h};queue.push(changed);return changed}return w})}return next;}
function Sparkline({index}:{index:number}){const lines=['"'0,30 9,28 17,31 25,20 33,23 41,11 49,17 57,14 65,17 73,5 81,9 90,2','0,30 9,25 17,27 25,17 33,21 41,14 49,16 57,8 65,12 73,6 81,9 90,2','0,29 9,32 17,23 25,25 33,16 41,20 49,10 57,15 65,7 73,12 81,3 90,6','0,24 9,22 17,27 25,15 33,17 41,11 49,17 57,14 65,4 73,8 81,2 90,4'];return <svg className=\"sparkline\" viewBox=\"0 0 90 40\"><defs><linearGradient id={'spark'+index} x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop stopColor=\"#f18854\" stopOpacity=\".15\"/><stop offset=\"1\" stopColor=\"#f18854\" stopOpacity=\"0\"/></linearGradient></defs><polygon points={"'`0,40 ${lines[index]} 90,40`} fill={`url(#spark${index})`}/><polyline points={lines[index]} fill="none" stroke="#e88a61" strokeWidth="1.8" strokeLinejoin="round"/></svg>}
function RevenueChart({period}:{period:string}){const [hover,setHover]=useState<number|null>(null);const [series,setSeries]=useState('"'revenue');const factor=period==='7 дней'?0.7:period==='Этот год'?1.25:1;const values=(series==='revenue'?[12,14,13,18,17,23,21,22,17,22,20,28,26,30,25,28,26,33,31,34,29,36,33,40,38,42,37,44,42,47]:[9,11,10,13,12,15,13,16,12,14,13,18,15,20,17,19,16,23,19,22,20,25,22,28,25,29,25,31,29,33]).map(v=>v*factor);const pts=values.map((v,i)=>[46+i*19.1,178-v*3]);const path=pts.map((p,i)=>"'`${i?'"'L':'M'}"'${p[0]},${p[1]}`).join('"' ');return <><div className=\"card-heading\"><div><h3>Динамика выручки</h3><p>Доходы вашего бизнеса за месяц</p></div><select className=\"small-select\" aria-label=\"Показатель графика\" value={series} onChange={e=>setSeries(e.target.value)}><option value=\"revenue\">Выручка</option><option value=\"expenses\">Расходы</option></select></div><div className=\"chart-summary\"><strong>{series==='revenue'?'"'$48,295.00'"':'"'$29,450.00'"'}</strong><span className=\"trend\"><Icon name=\"arrow\" size={12}/> 12,8%</span><span className=\"muted summary-note\">к прошлому периоду</span><span className=\"chart-legend\"><i/>Текущий период</span></div><div className=\"revenue-chart\" onMouseLeave={()=>setHover(null)}><svg viewBox=\"0 0 650 218\" role=\"img\" aria-label=\"График выручки с ростом за месяц\" onMouseMove={e=>{const r=e.currentTarget.getBoundingClientRect();setHover(Math.max(0,Math.min(29,Math.round(((e.clientX-r.left)/r.width*650-46)/19.1))))}}><defs><linearGradient id=\"area\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop stopColor=\"#ed8a57\" stopOpacity=\".16\"/><stop offset=\"1\" stopColor=\"#ed8a57\" stopOpacity=\".015\"/></linearGradient></defs>{[0,1,2,3].map((n)=><g key={n}><line x1=\"46\" x2=\"624\" y1={28+n*50} y2={28+n*50} stroke=\"#ececea\" strokeDasharray=\"3 4\"/><text x=\"0\" y={32+n*50}>{['"'$60k'"','"'$40k'"','"'$20k'"','"'$0'"'][n]}</text></g>)}<path d={"'`${path} L600,178 L46,178 Z`} fill="url(#area)"/><path d={path} stroke="#e87e47" fill="none" strokeWidth="2.7" strokeLinejoin="round" strokeLinecap="round"/>{[0,5,10,15,20,25,29].map((n,i)=><text key={n} x={46+n*19.1} y="207" textAnchor={i===6?'"'end':i===0?'start':'middle'}>{['1 июн','5 июн','10 июн','15 июн','20 июн','25 июн','30 июн'][i]}</text>)}{hover"'!==null&&<g><line x1={pts[hover][0]} x2={pts[hover][0]} y1="18" y2="178" stroke="#d8a285" strokeDasharray="4 3"/><circle cx={pts[hover][0]} cy={pts[hover][1]} r="4.5" fill="#e87e47" stroke="white" strokeWidth="2"/><rect x={Math.min(522,Math.max(46,pts[hover][0]-48))} y="1" width="100" height="26" rx="6" fill="#292a28"/><text x={Math.min(522,Math.max(46,pts[hover][0]-48))+50} y="18" textAnchor="middle" style={{fill:'"'white',fontSize:11}}>{hover+1} июн · "'${Math.round(values[hover]*1000).toLocaleString()}</text></g>}</svg></div></>}
const projects=[{name:'"'Редизайн веб-сайта',initial:'W',color:'lilac',type:'Дизайн и разработка',status:'В работе',progress:75,people:['АК','МС','ДВ'],due:'28 июн'},{name:'Мобильное приложение',initial:'M',color:'peach',type:'Продуктовый дизайн',status:'В работе',progress:48,people:['ЕП','МС'],due:'30 июн'},{name:'Фирменный стиль',initial:'B',color:'mint',type:'Брендинг',status:'Завершён',progress:100,people:['АК','ЕП','ДВ'],due:'24 июн'}];
function AppModal({title,subtitle,onClose,children}:{title:string;subtitle?:string;onClose:()=>void;children:React.ReactNode}){useEffect(()=>{const handle=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',handle);return()=>document.removeEventListener('keydown',handle)},[onClose]);return <div className=\"modal-overlay\" onClick={onClose}><section className=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-label={title} onClick={e=>e.stopPropagation()}><div className=\"modal-heading\"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className=\"icon-button\" onClick={onClose} aria-label=\"Закрыть\"><Icon name=\"close\"/></button></div>{children}</section></div>}
export function App(){
 const [widgets,setWidgets]=useState<Widget[]>(()=>{try{const saved=JSON.parse(localStorage.getItem('forma-layout')||'null');return Array.isArray(saved)&&saved.length&&saved.every(w=>w.id&&widgetNames[w.kind as WidgetKind]&&Number.isFinite(w.x)&&Number.isFinite(w.y)&&w.w>0&&w.h>0)?saved:initial}catch{return initial}});
 const [editing,setEditing]=useState(false);const [modal,setModal]=useState<string|null>(null);const [popover,setPopover]=useState<string|null>(null);const [period,setPeriod]=useState('Этот месяц');const [nav,setNav]=useState('Обзор');const [search,setSearch]=useState('');const [toast,setToast]=useState('');const [compact,setCompact]=useState(false);const [project,setProject]=useState<(typeof projects)[number]|null>(null);const [target,setTarget]=useState(60000);const [goalInput,setGoalInput]=useState('60000');const [invited,setInvited]=useState<string[]>([]);const [inviteEmail,setInviteEmail]=useState('');const [drag,setDrag]=useState<{id:string;dx:number;dy:number}|null>(null);const [drop,setDrop]=useState<Widget|null>(null);const gridRef=useRef<HTMLDivElement>(null);const dragRef=useRef<{widget:Widget;startX:number;startY:number;col:number;row:number;next:Widget}|null>(null);
 useEffect(()=>{localStorage.setItem('forma-layout',JSON.stringify(widgets))},[widgets]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3400);return()=>clearTimeout(t)}},[toast]);
 useEffect(()=>{const close=()=>setPopover(null);document.addEventListener('click',close);return()=>document.removeEventListener('click',close)},[]);
 const notify=(s:string)=>setToast(s);
 const togglePopover=(e:React.MouseEvent,name:string)=>{e.stopPropagation();setPopover(p=>p===name?null:name)};
 const beginDrag=(e:ReactPointerEvent,widget:Widget)=>{if(e.button"'!==0||window.innerWidth<760)return;e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);const r=gridRef.current!.getBoundingClientRect();dragRef.current={widget,startX:e.clientX,startY:e.clientY,col:(r.width+18)/12,row:compact?65:75,next:widget};setDrag({id:widget.id,dx:0,dy:0});};
 const moveDrag=(e:ReactPointerEvent)=>{const d=dragRef.current;if(!d)return;const dx=e.clientX-d.startX,dy=e.clientY-d.startY;d.next={...d.widget,x:Math.max(0,Math.min(12-d.widget.w,d.widget.x+Math.round(dx/d.col))),y:Math.max(0,d.widget.y+Math.round(dy/d.row))};setDrag({id:d.widget.id,dx,dy});setDrop(d.next)};
 const endDrag=()=>{const d=dragRef.current;if(d){if(d.next.x!==d.widget.x||d.next.y!==d.widget.y){setWidgets(w=>place(w,d.next));notify('"'Расположение виджетов сохранено')}dragRef.current=null;setDrag(null);setDrop(null)}};
 const addWidget=(kind:WidgetKind)=>{const small=['revenue','customers','orders','conversion'].includes(kind);const w=small?3:kind==='chart'||kind==='projects'?8:4;let y=0,x=0;outer:for(y=0;y<100;y++){for(x=0;x<=12-w;x++){const candidate={id:'new',kind,x,y,w,h:small?2:4};if("'!widgets.some(item=>overlaps(candidate,item)))break outer}}setWidgets(items=>[...items,{id:kind+'"'-'+Date.now(),kind,x,y,w,h:small?2:4}]);setModal(null);notify('Виджет добавлен на дашборд')};
 const exportReport=()=>{const blob=new Blob(['\\uFEFFПоказатель;Значение\\nВыручка;48295\\nКлиенты;2420\\nЗаказы;1386\\nКонверсия;3.62%\\n\\nПроект;Статус;Прогресс\\n'+projects.map(p=>"'`${p.name};${p.status};${p.progress}%`).join('"'\\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='forma-report-june-2026.csv';a.click();URL.revokeObjectURL(url);notify('Отчёт скачан')};
 const shownWidgets=nav==='Аналитика'?widgets.filter(w=>w.kind"'!=='"'projects'&&w.kind"'!=='"'goal'):nav==='Проекты'?widgets.filter(w=>w.kind==='projects'||w.kind==='goal'||w.kind==='activity'):widgets;
 const activeWidgets=nav==='Обзор'?shownWidgets:shownWidgets.reduce<Widget[]>((acc,w)=>{let y=0,x=0;outer:for(y=0;y<100;y++){for(x=0;x<=12-w.w;x++){if("'!acc.some(a=>overlaps({...w,x,y},a)))break outer}}return [...acc,{...w,x,y}]},[]);
 const factor=period==='"'7 дней'?.26:period==='Этот год'?8.4:1;
 const renderWidget=(w:Widget)=>{if(['revenue','customers','orders','conversion'].includes(w.kind)){const index=['revenue','customers','orders','conversion'].indexOf(w.kind);return <div className=\"metric-content\"><div className=\"metric-label\"><span className={'metric-icon metric-icon-'+index}><Icon name={(['wallet','users','cart','chart'] as IconName[])[index]} size={17}/></span><span>{widgetNames[w.kind]}</span></div><div className=\"metric-number\">{index===0?'"'$'"'+Math.round(48295*factor).toLocaleString('en-US'):index===1?Math.round(2420*factor).toLocaleString('en-US'):index===2?Math.round(1386*factor).toLocaleString('en-US'):'3.62%'}<Sparkline index={index}/></div><div className=\"metric-footer\"><span className=\"trend\"><Icon name=\"arrow\" size={12}/>{['12,8','8,2','5,4','2,1'][index]}%</span><span>к прошлому периоду</span></div></div>}
 if(w.kind==='chart')return <RevenueChart period={period}/>;
 if(w.kind==='traffic')return <><div className=\"card-heading\"><div><h3>Источники трафика</h3><p>Откуда приходят ваши клиенты</p></div></div><div className=\"traffic-content\"><div className=\"donut\"><svg viewBox=\"0 0 180 180\"><circle cx=\"90\" cy=\"90\" r=\"68\" fill=\"none\" stroke=\"#f2f0ec\" strokeWidth=\"24\"/>{[{value:44,offset:0,color:'#e58a51'},{value:28,offset:44,color:'#f2ba91'},{value:18,offset:72,color:'#d3d7c6'},{value:10,offset:90,color:'#ecece6'}].map(s=><circle key={s.offset} cx=\"90\" cy=\"90\" r=\"68\" fill=\"none\" stroke={s.color} strokeWidth=\"24\" strokeDasharray={"'`${s.value*4.272-4} ${427.2-s.value*4.272+4}`} strokeDashoffset={-s.offset*4.272} transform="rotate(-90 90 90)"/>)}</svg><div><span>Всего посетителей</span><strong>{Math.round(24680*factor).toLocaleString('"'en-US')}</strong><span className=\"trend\">↗ 8,4%</span></div></div><div className=\"traffic-legend\">{[['#e58a51','Прямые переходы','44%'],['#f2ba91','Поиск','28%'],['#d3d7c6','Социальные сети','18%'],['#ecece6','Другое','10%']].map(([color,label,val])=><div key={label}><i style={{background:color}}/><span>{label}</span><b>{val}</b></div>)}</div></div></>;
 if(w.kind==='projects')return <><div className=\"card-heading\"><div><h3>Последние проекты <span className=\"count-badge\">6</span></h3><p>От идеи до результата</p></div><button className=\"text-button\" onClick={()=>setModal('projects')}>Все проекты <Icon name=\"chevron\" size={14}/></button></div><div className=\"project-table\"><div className=\"table-head\"><span>Название проекта</span><span>Статус</span><span>Прогресс</span><span>Команда</span></div>{projects.map(p=><button className=\"project-row\" key={p.name} onClick={()=>{setProject(p);setModal('project')}}><span className=\"project-name\"><span className={'project-logo '+p.color}>{p.initial}</span><span><b>{p.name}</b><small>{p.type}</small></span></span><span className={'status '+(p.progress===100?'complete':'')}><i/>{p.status}</span><span className=\"progress-cell\"><span className=\"progress-track\"><i style={{width:p.progress+'%',background:p.progress===100?'#8eaa8d':undefined}}/></span><small>{p.progress}%</small></span><span className=\"avatars\">{p.people.map((person,i)=><span key={person} className={'avatar avatar-'+i}>{person}</span>)}</span></button>)}</div><div className=\"project-footer\"><span><i className=\"live-dot\"/> Всё идёт по плану</span><span>3 из 6 проектов</span></div></>;
 if(w.kind==='goal')return <><div className=\"card-heading\"><div><h3>Цель на месяц</h3><p>Маленькие шаги. Большие результаты.</p></div><span className=\"goal-icon\"><Icon name=\"target\" size={19}/></span></div><div className=\"goal-amount\"><strong>"'$48,295</strong><span>из ${target.toLocaleString('"'en-US')}</span></div><div className=\"goal-progress\"><i style={{width:Math.min(100,48295/target*100)+'%'}}/></div><div className=\"goal-progress-label\"><span>{Math.round(48295/target*100)}% выполнено</span><strong>Осталось 6 дней</strong></div><div className=\"goal-note\"><span>✧</span><p>Отличный темп"'! Ещё немного —<br/>и цель будет достигнута.</p></div><button className="goal-link" onClick={()=>{setGoalInput(String(target));setModal('"'goal')}}>Настроить цель <Icon name=\"arrow\" size={14}/></button></>;
 return <><div className=\"card-heading\"><div><h3>Активность команды</h3><p>Последние обновления</p></div></div><div className=\"activity-list\">{[['АК','Алексей завершил задачу','Макет главной страницы','10 минут назад'],['МС','Мария добавила комментарий','Редизайн веб-сайта','32 минуты назад'],['ДВ','Дмитрий загрузил файлы','Фирменный стиль','1 час назад']].map((a,i)=><div key={a[0]}><span className={'avatar avatar-'+i}>{a[0]}</span><section><b>{a[1]}</b><p>{a[2]}</p><small>{a[3]}</small></section></div>)}</div></>;
